const rows = $input.all().map(r => r.json).filter(r => r.key);
const config = {};
for (const row of rows) { config[row.key] = row.value; }
return [{ json: {
  newsletterName: config.newsletter_name || 'Weekly Digest',
  topics: (config.topics || '').split(',').map(t => t.trim()).filter(Boolean),
  recipientEmail: config.recipient_email || '',
  fromName: config.from_name || 'Newsletter Bot',
  tone: config.tone || 'informative',
  itemCount: parseInt(config.items_per_issue) || 5,
  includeAiCommentary: config.include_ai_commentary !== 'false',
  audienceDescription: config.audience_description || ''
} }];

// Collect all search results from this and previous loop iterations
// This runs after ALL topics have been searched
const config = $('Parse Config').first().json;
const allSearchResults = $('Search Topic').all();
const allItems = [];
for (const result of allSearchResults) {
  const items = result.json?.results || [];
  for (const item of items) {
    allItems.push({
      title: item.title,
      url: item.url,
      snippet: (item.content || item.snippet || '').slice(0, 400),
      score: item.score || 0
    });
  }
}
// Deduplicate by URL
const seen = new Set();
const unique = allItems.filter(item => {
  if (seen.has(item.url)) return false;
  seen.add(item.url);
  return true;
});
unique.sort((a,b) => b.score - a.score);
return [{ json: { config, articles: unique.slice(0, 30), issueDate: new Date().toISOString().split('T')[0] } }];

values.content:
Curate this week's newsletter.

Newsletter: {{ $json.config.newsletterName }}
Topics covered: {{ $json.config.topics.join(', ') }}
Audience: {{ $json.config.audienceDescription || 'general' }}
Tone: {{ $json.config.tone }}
Items to select: {{ $json.config.itemCount }}
Issue date: {{ $json.issueDate }}
Include AI commentary: {{ $json.config.includeAiCommentary }}

Available articles this week:
{{ $json.articles.map((a, i) => `${i+1}. ${a.title}\n   URL: ${a.url}\n   Preview: ${a.snippet}`).join('\n\n') }}

Return this JSON:
{
  "issue_number_note": "week of issue date formatted nicely",
  "editor_intro": "2-3 sentence intro from the editor — what's notable about this week's content, any theme, honest about if it was a slow week",
  "selected_items": [
    {
      "rank": 1,
      "title": "article title",
      "url": "article url",
      "why_selected": "one sentence — why this is worth reading",
      "commentary": "2-4 sentences of editorial commentary — context, point of view, what to take away. Not a summary of the headline.",
      "tag": "one word category tag"
    }
  ],
  "quick_links": [
    { "title": "title", "url": "url", "one_liner": "one line description" }
  ],
  "editors_pick": 1,
  "closing_note": "1-2 sentence closing from the editor — can be casual, forward-looking, or a question to readers"
}

