const raw = $input.first().json.text || $input.first().json.content?.[0]?.text || '';
let newsletter;
try { newsletter = JSON.parse(raw.replace(/```json|```/g,'').trim()); } catch(e) { return [{ json: { error: 'Parse error', raw } }]; }
const agg = $('Aggregate Articles').first().json;
newsletter._meta = { config: agg.config, issueDate: agg.issueDate };
return [{ json: newsletter }];

const n = $input.first().json;
const m = n._meta;
const config = m.config;
function esc(s) { return String(s||'').replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;'); }

const itemBlocks = (n.selected_items||[]).map((item, idx) => {
  const isEditorsPick = item.rank === n.editors_pick;
  return `<div style="padding:20px 0;border-bottom:1px solid #f3f4f6${idx === 0 ? ';border-top:1px solid #f3f4f6' : ''}">
    ${isEditorsPick ? '<div style="font-size:11px;font-weight:700;text-transform:uppercase;color:#f59e0b;margin-bottom:6px">★ Editor's Pick</div>' : ''}
    <div style="display:flex;gap:8px;align-items:flex-start;margin-bottom:6px">
      <span style="background:#f3f4f6;color:#6b7280;font-size:11px;padding:2px 8px;border-radius:8px;white-space:nowrap;margin-top:2px">${esc(item.tag||'')}</span>
      <a href="${esc(item.url)}" style="font-size:16px;font-weight:600;color:#1a1a1a;text-decoration:none;line-height:1.4">${esc(item.title)}</a>
    </div>
    <div style="font-size:13px;color:#6b7280;margin-bottom:8px;font-style:italic">${esc(item.why_selected)}</div>
    <p style="font-size:14px;line-height:1.75;color:#374151;margin:0">${esc(item.commentary)}</p>
  </div>`;
}).join('');

const quickLinks = (n.quick_links||[]).map(ql => `<div style="padding:8px 0;border-bottom:1px solid #f3f4f6">
  <a href="${esc(ql.url)}" style="font-size:14px;font-weight:600;color:#2563eb;text-decoration:none">${esc(ql.title)}</a>
  <span style="font-size:13px;color:#6b7280;margin-left:6px">— ${esc(ql.one_liner)}</span>
</div>`).join('');

const html = `<!DOCTYPE html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>${esc(config.newsletterName)}</title></head>
<body style="margin:0;padding:0;background:#f9f9f7;font-family:Georgia,'Times New Roman',serif">
<div style="max-width:600px;margin:0 auto;padding:16px">
  <div style="background:#1a1a1a;color:#fff;padding:28px 32px;border-radius:10px 10px 0 0">
    <div style="font-size:22px;font-weight:700;letter-spacing:-0.3px">${esc(config.newsletterName)}</div>
    <div style="font-size:13px;color:#9ca3af;margin-top:4px">${esc(n.issue_number_note||m.issueDate)}</div>
  </div>
  <div style="background:#fff;padding:24px 32px;border:1px solid #e5e5e3;border-top:none">
    <p style="font-size:15px;line-height:1.8;color:#374151;margin:0">${esc(n.editor_intro)}</p>
  </div>
  <div style="background:#fff;padding:0 32px;border:1px solid #e5e5e3;border-top:none">
    ${itemBlocks}
  </div>
  ${quickLinks ? `<div style="background:#f8f8f6;padding:18px 32px;border:1px solid #e5e5e3;border-top:none">
    <div style="font-size:11px;font-weight:700;text-transform:uppercase;color:#9ca3af;margin-bottom:10px">Quick links</div>
    ${quickLinks}
  </div>` : ''}
  <div style="background:#fff;padding:18px 32px;border:1px solid #e5e5e3;border-top:3px solid #f3f3f0">
    <p style="font-size:14px;line-height:1.75;color:#6b7280;margin:0;font-style:italic">${esc(n.closing_note)}</p>
  </div>
  <div style="background:#1a1a1a;color:#4b5563;font-size:11px;padding:14px 32px;border-radius:0 0 10px 10px;text-align:center;font-family:sans-serif">
    ${esc(config.newsletterName)} · ${esc(m.issueDate)} · ${(n.selected_items||[]).length} articles curated
  </div>
</div></body></html>`;

return [{ json: { html, recipientEmail: config.recipientEmail, newsletterName: config.newsletterName, issueDate: m.issueDate, itemCount: (n.selected_items||[]).length, newsletter: n } }];
